typedef struct {
    char name[12];
    int age;
} person;
person list[2] =
    {{"Ana", 31}, {"Bo", 27}};
for (int i = 0; i < 2; i++)
    printf("%s is %d\n",
           list[i].name, list[i].age);

person *p = malloc(sizeof *p);
if (p == NULL)
    return 1;
strcpy(p->name, "Ana");
p->age = 31;
printf("%s %d\n", p->name, p->age);
free(p);
